style.css:
@-moz-document domain("youtube.com") {
/* ========== PALETA ========== */
  :root {
    --bg: #E6EEF4;
    --bg-card: #EDF3F7;
    --bg-elevated: #F0F5F8;
    --text: #1E3A4A;
    --text-sec: #5A7380;
    --accent: #7BA3B5;
    --accent-hover: #6B9AAB;
    --border: #D5E3EC;
    --shadow: 0 4px 20px rgba(30, 58, 74, 0.07);
    --radius: 16px;
    --radius-sm: 12px;

    --yt-spec-base-background: var(--bg) !important;
    --yt-spec-raised-background: var(--bg-card) !important;
    --yt-spec-menu-background: var(--bg-elevated) !important;
    --yt-spec-text-primary: var(--text) !important;
    --yt-spec-text-secondary: var(--text-sec) !important;
    --yt-spec-text-primary-inverse: #ffffff !important;
    --yt-spec-brand-button-text: var(--text) !important;
    --yt-spec-static-brand-red: var(--accent) !important;
    --yt-spec-brand-red: var(--accent) !important;
    --yt-spec-call-to-action: var(--accent-hover) !important;
    --yt-spec-10-percent-layer: rgba(30, 58, 74, 0.06) !important;
    --yt-spec-badge-chip-background: var(--bg-elevated) !important;
    --yt-spec-button-chip-background-hover: rgba(123, 163, 181, 0.15) !important;
    --yt-spec-general-background-a: var(--bg) !important;
    --yt-spec-general-background-b: var(--bg-card) !important;
    --yt-spec-general-background-c: var(--bg-elevated) !important;
    --yt-spec-additive-background: rgba(30, 58, 74, 0.04) !important;
    --yt-spec-outline: var(--border) !important;
  }

  /* ========== FONDO GENERAL ========== */
  html, body, ytd-app, #content, ytd-page-manager, #page-manager {
    background-color: var(--bg) !important;
  }

  /* ========== LOGO DE YOUTUBE (versión más fuerte) ========== */
  ytd-topbar-logo-renderer #logo-icon,
  #logo-icon,
  ytd-logo #logo-icon {
    filter: invert(58%) sepia(18%) saturate(650%) hue-rotate(155deg) brightness(95%) contrast(85%) !important;
  }

  /* Forzar que el triángulo también cambie */
  ytd-topbar-logo-renderer #logo-icon path,
  #logo-icon path {
    fill: currentColor !important;
  }

  /* ========== HEADER ========== */
  ytd-masthead, #masthead-container, #background.ytd-masthead {
    background-color: var(--bg-card) !important;
    border-bottom: 1px solid var(--border) !important;
    box-shadow: var(--shadow) !important;
  }

  ytd-searchbox #container, 
  ytd-searchbox #search-input {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    border-radius: 24px !important;
    color: var(--text) !important;
  }

  ytd-searchbox #search-icon-legacy {
    background-color: var(--accent) !important;
    border-radius: 0 24px 24px 0 !important;
  }

  /* ========== SIDEBAR ========== */
  #guide-content, ytd-mini-guide-renderer, 
  ytd-guide-renderer, tp-yt-app-drawer {
    background-color: var(--bg-card) !important;
    border-right: 1px solid var(--border) !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background-color: rgba(123, 163, 181, 0.12) !important;
    border-radius: 12px !important;
  }

  /* ========== GRID (ya está bien, no tocar) ========== */
  ytd-rich-grid-renderer {
    --ytd-rich-grid-items-per-row: 3 !important;
  }

  ytd-rich-item-renderer {
    max-width: 380px !important;
  }

  /* ========== TARJETAS DE VIDEO ========== */
  ytd-rich-item-renderer, 
  ytd-video-renderer, 
  ytd-grid-video-renderer,
  ytd-compact-video-renderer {
    background-color: var(--bg-card) !important;
    border-radius: var(--radius) !important;
    overflow: hidden;
    box-shadow: var(--shadow);
    border: 1px solid transparent;
    transition: all 0.25s ease;
  }

  ytd-rich-item-renderer:hover, 
  ytd-video-renderer:hover {
    border-color: var(--border);
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(30, 58, 74, 0.1);
  }

  ytd-thumbnail, #thumbnail, .yt-core-image {
    border-radius: var(--radius-sm) !important;
  }

  #video-title, .title {
    color: var(--text) !important;
    font-weight: 500 !important;
  }

  #metadata-line, .ytd-video-meta-block, #channel-name {
    color: var(--text-sec) !important;
  }

  /* ========== BARRA DE PROGRESO (ya está bien) ========== */
  .ytp-play-progress {
    background: var(--accent) !important;
  }

  .ytp-load-progress {
    background: rgba(123, 163, 181, 0.35) !important;
  }

  .ytp-scrubber-button,
  .ytp-scrubber-button:hover {
    background: var(--accent) !important;
    border-color: var(--accent) !important;
  }

  .ytp-swatch-background-color,
  .ytp-swatch-color {
    background-color: var(--accent) !important;
  }

  /* ========== BOTÓN DE SUSCRIBIRSE ========== */
  ytd-subscribe-button-renderer yt-button-shape button,
  ytd-subscribe-button-renderer .yt-spec-button-shape-next,
  #subscribe-button yt-button-shape button,
  ytd-button-renderer#subscribe-button button {
    background-color: var(--accent) !important;
    color: white !important;
    border-radius: 22px !important;
    border: none !important;
    padding: 0 18px !important;
    font-weight: 500 !important;
    transition: background-color 0.2s ease;
  }

  ytd-subscribe-button-renderer yt-button-shape button:hover,
  ytd-subscribe-button-renderer .yt-spec-button-shape-next:hover,
  #subscribe-button yt-button-shape button:hover {
    background-color: var(--accent-hover) !important;
  }

  /* Cuando ya estás suscrito */
  ytd-subscribe-button-renderer[subscribed] yt-button-shape button,
  ytd-subscribe-button-renderer[subscribed] .yt-spec-button-shape-next {
    background-color: var(--bg-elevated) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
  }

  /* ========== PÁGINA DE VIDEO ========== */
  ytd-watch-flexy {
    background-color: var(--bg) !important;
  }

  ytd-compact-video-renderer {
    background-color: var(--bg-card) !important;
    border-radius: var(--radius-sm) !important;
    margin-bottom: 8px !important;
    padding: 6px !important;
  }

  ytd-video-secondary-info-renderer,
  ytd-comments, #comments {
    background-color: var(--bg-card) !important;
    border-radius: var(--radius) !important;
    padding: 16px !important;
    border: 1px solid var(--border) !important;
  }

  /* ========== BOTONES GENERALES ========== */
  ytd-button-renderer, yt-button-shape button,
  .yt-spec-button-shape-next {
    border-radius: 20px !important;
  }

  /* ========== CHIPS ========== */
  yt-chip-cloud-chip-renderer {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    color: var(--text) !important;
    border-radius: 20px !important;
  }

  yt-chip-cloud-chip-renderer[selected] {
    background-color: var(--accent) !important;
    color: white !important;
    border-color: var(--accent) !important;
  }

  /* ========== MENÚS ========== */
  tp-yt-paper-listbox,
  ytd-menu-popup-renderer {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    border-radius: var(--radius-sm) !important;
    box-shadow: var(--shadow) !important;
  }

  /* ========== SCROLLBAR ========== */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: var(--bg);
  }
  ::-webkit-scrollbar-thumb {
    background: var(--accent);
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--accent-hover);
  }

  /* Quitar algo de ruido */
  #masthead-ad,
  ytd-ad-slot-renderer,
  ytd-banner-promo-renderer {
    display: none !important;
  }
}
